#include <iostream>

int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int* ptr = arr;  // Points to first element

    // Array indexing and pointer arithmetic are equivalent
    std::cout << "arr[0]: " << arr[0] << ", *ptr: " << *ptr << std::endl;
    std::cout << "arr[1]: " << arr[1] << ", *(ptr+1): " << *(ptr + 1) << std::endl;

    // Loop using pointer arithmetic
    std::cout << "Using pointer: ";
    for (int i = 0; i < 5; i++) {
        std::cout << *(ptr + i) << " ";
    }
    std::cout << std::endl;

    // ptr++ moves to next element
    std::cout << "ptr++ traversal: ";
    for (int i = 0; i < 5; i++) {
        std::cout << *ptr << " ";
        ptr++;
    }
    std::cout << std::endl;

    return 0;
}

