    ref = 100;
    std::cout << "After ref = 100:" << std::endl;
    std::cout << "num: " << num << std::endl;
    std::cout << "ref: " << ref << std::endl;

    // Both have the same address
    std::cout << "Address of num: " << &num << std::endl;
    std::cout << "Address of ref: " << &ref << std::endl;

    return 0;
}

