#include <iostream>

void leakyFunction() {
    int* data = new int[1000];
    // Do some work...
    // Oops! Forgot delete[] data;
    // Memory leak! 4000 bytes lost forever
}

void safeFunction() {
    int* data = new int[1000];
    // Do some work...
    delete[] data;  // Clean up!
    data = nullptr;
}

int main() {
    // Each call leaks memory
    for (int i = 0; i < 100000; i++) {
        // leakyFunction();  // DON'T DO THIS!
        safeFunction();      // Good practice
    }

    std::cout << "Memory managed safely!" << std::endl;
    return 0;
}

